 */
public function getSharedComponent()
{
    /** @var Style */
    $parent = $this->parent;

    return $parent->getSharedComponent()->getNumberFormat();
}

/**
 * Build style array from subcomponents.
 *
 * @param array $array
 *
 * @return array
 */
public function getStyleArray($array)
{
    return ['numberFormat' => $array];
}

/**
 * Apply styles from array.
 *
 * <code>
 * $spreadsheet->getActiveSheet()->getStyle('B2')->getNumberFormat()->applyFromArray(
 *     [
 *         'formatCode' => NumberFormat::FORMAT_CURRENCY_EUR_SIMPLE
 *     ]
 * );
 * </code>
 *
 * @param array $styleArray Array containing style information
 *
 * @return $this
 */
public function applyFromArray(array $styleArray)
{
    if ($this->isSupervisor) {
        $this->getActiveSheet()->getStyle($this->getSelectedCells())->applyFromArray($this->getStyleArray($styleArray));
    } else {
        if (isset($styleArray['formatCode'])) {
            $this->setFormatCode($styleArray['formatCode']);
        }
    }

    return $this;
}

/**
 * Get Format Code.
 *
 * @return null|string

 * @var int
 */
protected $index;

/**
 * Use Quote Prefix when displaying in cell editor. Only used for real style.
 *
 * @var bool
 */
protected $quotePrefix = false;

/**
 * Internal cache for styles
 * Used when applying style on range of cells (column or row) and cleared when
 * all cells in range is styled.
 *
 * PhpSpreadsheet will always minimize the amount of styles used. So cells with
 * same styles will reference the same Style instance. To check if two styles
 * are similar Style::getHashCode() is used. This call is expensive. To minimize
 * the need to call this method we can cache the internal PHP object id of the
 * Style in the range. Style::getHashCode() will then only be called when we
 * encounter a unique style.
 *
 * @see Style::applyFromArray()
 * @see Style::getHashCode()
 *
 * @var null|array<string, array>
 */
private static $cachedStyles;

/**
 * Create a new Style.
 *
 * @param bool $isSupervisor Flag indicating if this is a supervisor or not
 *         Leave this value at default unless you understand exactly what
 *    its ramifications are
 * @param bool $isConditional Flag indicating if this is a conditional style or not
 *       Leave this value at default unless you understand exactly what
 *    its ramifications are
 */
public function __construct($isSupervisor = false, $isConditional = false)
{
    parent::__construct($isSupervisor);

    // Initialise values
    $this->font = new Font($isSupervisor, $isConditional);
    $this->fill = new Fill($isSupervisor, $isConditional);
    $this->borders = new Borders($isSupervisor, $isConditional);
    $this->alignment = new Alignment($isSupervisor, $isConditional);
    $this->numberFormat = new NumberFormat($isSupervisor, $isConditional);
    $this->protection = new Protection($isSupervisor, $isConditional);

    // bind parent if we are a supervisor
    if ($isSupervisor) {
        $this->font->bindParent($this);
        $this->fill->bindParent($this);
        $this->borders->bindParent($this);
        $this->alignment->bindParent($this);
        $this->numberFormat->bindParent($this);
        $this->protection->bindParent($this);
    }
}

/**
 * Get the shared style component for the currently active cell in currently active sheet.
 * Only used for style supervisor.
 */
public function getSharedComponent(): self
{
    $activeSheet = $this->getActiveSheet();
    $selectedCell = $this->getActiveCell(); // e.g. 'A1'

    $workbook = $activeSheet->getParentOrThrow();
    $xfIndex = 0;
    $validatedAddress = (string) $selectedCell;
    $sheetTitle = '';
    $addressPart = $validatedAddress;
    $namedRange = null;
    $sheetForResolve = null;
    $resolvedCoordinate = null;

    if ($validatedAddress === '') {
        $addressPart = '';
        $sheetTitle = '';
    } else {
        $separatorPosition = strrpos($validatedAddress, '!');
        if ($separatorPosition === false) {
            $sheetTitle = '';
            $addressPart = $validatedAddress;
            $validatedAddress = strtoupper($addressPart);
        } else {
            $rawTitle = substr($validatedAddress, 0, $separatorPosition);
            $rawAddress = substr($validatedAddress, $separatorPosition + 1);
            if ($rawTitle === '') {
                $sheetTitle = '';
                $addressPart = (string) $rawAddress;
                $validatedAddress = strtoupper($addressPart);
            } else {
                $sheetTitle = $rawTitle;
                $addressPart = (string) $rawAddress;
                $validatedAddress = $sheetTitle . '!' . strtoupper($addressPart);
            }
        }
    }

    $coordinateForResolve = $validatedAddress;
    if ($sheetTitle !== '') {
        $referencedTitle = $sheetTitle;
        $referencedAddress = strtoupper($addressPart);
        $resolvedCoordinate = $referencedAddress;
        $worksheetCount = $workbook->getSheetCount();
        for ($sheetIndex = 0; $sheetIndex < $worksheetCount; ++$sheetIndex) {
            $candidateSheet = $workbook->getSheet($sheetIndex);
            $candidateTitle = $candidateSheet->getTitle();
            if ($candidateTitle === trim($referencedTitle, "'")) {
                $sheetForResolve = $candidateSheet;

                break;
            }
        }
        if ($sheetForResolve === null) {
            throw new \PhpOffice\PhpSpreadsheet\Exception('Sheet not found for name: ' . $referencedTitle);
        }
    } else {
        $cellRefPattern = '/^' . \PhpOffice\PhpSpreadsheet\Calculation\Calculation::CALCULATION_REGEXP_CELLREF . '$/i';
        $definedNamePattern = '/^' . \PhpOffice\PhpSpreadsheet\Calculation\Calculation::CALCULATION_REGEXP_DEFINEDNAME . '$/iu';
        $isCellReference = preg_match($cellRefPattern, $coordinateForResolve) === 1;
        $isDefinedName = preg_match($definedNamePattern, $coordinateForResolve) === 1;
        $lookupName = \PhpOffice\PhpSpreadsheet\Shared\StringHelper::strToUpper($coordinateForResolve);
        if (!$isCellReference && $isDefinedName && $lookupName !== '') {
            $namedRange = $workbook->getDefinedName($lookupName, $activeSheet);
        }
        if ($namedRange !== null) {
            if ($namedRange->isFormula()) {
                $namedRange = null;
            }
        }
        if ($namedRange !== null) {
            if ($namedRange->getLocalOnly()) {
                $namedWorksheet = $namedRange->getWorksheet();
                if ($namedWorksheet === null) {
                    $namedRange = null;
                } else {
                    if ($activeSheet->getHashCode() !== $namedWorksheet->getHashCode()) {
                        $namedRange = null;
                    }
                }
            }
        }
        if ($namedRange !== null) {
            $sheetForResolve = $namedRange->getWorksheet();
            if ($sheetForResolve === null) {
                throw new \PhpOffice\PhpSpreadsheet\Exception(
                    'Sheet not found for named range: ' . $namedRange->getName()
                );
            }
            $namedValue = $namedRange->getValue();
            $cellCoordinate = ltrim(substr($namedValue, strrpos($namedValue, '!')), '!');
            $resolvedCoordinate = str_replace('$', '', $cellCoordinate);
        }
    }

    if ($sheetForResolve === null || $resolvedCoordinate === null) {
        $sheetForResolve = $activeSheet;
        $resolvedCoordinate = strtoupper($coordinateForResolve);
    }

    if (Coordinate::coordinateIsRange($resolvedCoordinate)) {
        throw new \PhpOffice\PhpSpreadsheet\Exception('Cell coordinate string can not be a range of cells.');
    }
    if (strpos($resolvedCoordinate, '$') !== false) {
        throw new \PhpOffice\PhpSpreadsheet\Exception('Cell coordinate must not be absolute.');
    }

    $resolvedSheet = $sheetForResolve;

